// Generated bytes are checked in, so ordinary builds need no toolchain.
// This runs `zig build` (build.zig) with the pinned Zig, which compiles
// src/root.zig and, with its clang, zlib and the LZMA SDK, unchanged, to
// wasm32-freestanding, and writes the module as base64 into src/binary.ts;
// --check verifies the inputs' digest.
import { execFileSync } from "node:child_process";
import { createHash } from "node:crypto";
import {
  copyFileSync,
  mkdtempSync,
  readdirSync,
  readFileSync,
  rmSync,
  writeFileSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { fileURLToPath } from "node:url";
import { findZig, ZIG_VERSION } from "../../tools/zig.ts";

const here = fileURLToPath(new URL(".", import.meta.url));
const zlib = fileURLToPath(new URL("../../vendor/zlib/", import.meta.url));
const lzma = fileURLToPath(new URL("../../vendor/lzma-sdk/C/", import.meta.url));

/** The C and headers of a directory, sorted: more than build.zig compiles, never less. */
const cFiles = (dir: string) =>
  readdirSync(dir)
    .filter((name) => /\.[ch]$/.test(name))
    .sort()
    .map((name) => join(dir, name));

const inputs = [
  fileURLToPath(import.meta.url),
  join(here, "build.zig"),
  join(here, "build.zig.zon"),
  join(here, "src/root.zig"),
  ...cFiles(join(here, "include")),
  ...cFiles(zlib),
  join(zlib, "LICENSE"),
  ...cFiles(lzma),
];
const digest = createHash("sha256").update(ZIG_VERSION);
for (const file of inputs) {
  digest.update(readFileSync(file));
}

const inputDigest = digest.digest("hex");
const target = join(here, "src/binary.ts");
if (process.argv.includes("--check")) {
  if (!readFileSync(target, "utf8").includes(`inputs: ${inputDigest}`)) {
    throw new Error("compression inputs changed; run pnpm --filter @swf2es/compress build:wasm");
  }
} else {
  const zig = findZig();
  // Fresh caches and prefix each time, so nothing of an earlier build is reused.
  const work = mkdtempSync(join(tmpdir(), "swf2es-compress-"));
  try {
    execFileSync(zig, ["build", "--prefix", work], {
      cwd: here,
      stdio: "inherit",
      env: {
        ...process.env,
        ZIG_LOCAL_CACHE_DIR: join(work, "cache"),
        ZIG_GLOBAL_CACHE_DIR: join(work, "global"),
      },
    });
    const bytes = readFileSync(join(work, "bin/compress.wasm"));
    const module = await WebAssembly.compile(bytes);
    if (WebAssembly.Module.imports(module).length) {
      throw new Error(
        `compression must import nothing: ${JSON.stringify(WebAssembly.Module.imports(module))}`,
      );
    }

    writeFileSync(
      target,
      `// Generated by packages/compress/build.ts; zlib is under the zlib license, the LZMA SDK in the public domain.\n// inputs: ${inputDigest}\nexport const binary =\n  "${bytes.toString("base64")}";\n`,
    );
    copyFileSync(join(zlib, "LICENSE"), join(here, "LICENSE.zlib"));
    console.log(`compress: ${bytes.length} bytes`);
  } finally {
    rmSync(work, { recursive: true, force: true });
  }
}
